  static KidMate? getAnimalByLevel(int level) {
    if (level < 1) return robotsAndHomies.first;
    if (level > robotsAndHomies.length) return robotsAndHomies.last;
    try {
      return robotsAndHomies.firstWhere((a) => a.dayLevel == level);
    } catch (_) {
      return robotsAndHomies[level - 1];
    }
  }

  static KidMate? getAnimalById(String id) {
    try {
      return robotsAndHomies.firstWhere((a) => a.id == id);
    } catch (_) {
      return null;
    }
  }
}
